+    (() => {
+      const root = document.documentElement;
+      const wrap = document.getElementById('bowl-wrap');
+      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
+      let targetX = 0;
+      let targetY = 0;
+      let currentX = 0;
+      let currentY = 0;
+      let frame;
+
+      const render = () => {
+        currentX += (targetX - currentX) * 0.075;
+        currentY += (targetY - currentY) * 0.075;
+        root.style.setProperty('--pointer-x', currentX.toFixed(3));
+        root.style.setProperty('--pointer-y', currentY.toFixed(3));
+        root.style.setProperty('--tilt-x', `${(-currentY * 2.3).toFixed(2)}deg`);
+        root.style.setProperty('--tilt-y', `${(currentX * 3.1).toFixed(2)}deg`);
+        root.style.setProperty('--shift-x', `${(currentX * 8).toFixed(2)}px`);
+        root.style.setProperty('--shift-y', `${(currentY * 5).toFixed(2)}px`);
+        if (Math.abs(targetX - currentX) > .001 || Math.abs(targetY - currentY) > .001) {
+          frame = requestAnimationFrame(render);
+        } else {
+          frame = undefined;
+        }
+      };
+
+      const wake = () => {
+        if (!frame && !reduceMotion.matches) frame = requestAnimationFrame(render);
+      };
+
+      window.addEventListener('pointermove', (event) => {
+        if (reduceMotion.matches || event.pointerType === 'touch') return;
+        targetX = (event.clientX / window.innerWidth - .5) * 2;
+        targetY = (event.clientY / window.innerHeight - .5) * 2;
+        wake();
+      }, { passive: true });
+
+      window.addEventListener('pointerleave', () => {
+        targetX = 0;
+        targetY = 0;
+        wake();
+      });
+
+      window.addEventListener('blur', () => {
+        targetX = 0;
+        targetY = 0;
+        wake();
+      });
+
+      reduceMotion.addEventListener?.('change', () => {
+        if (reduceMotion.matches) {
+          cancelAnimationFrame(frame);
+          frame = undefined;
+          root.style.removeProperty('--tilt-x');
+          root.style.removeProperty('--tilt-y');
+          root.style.removeProperty('--shift-x');
+          root.style.removeProperty('--shift-y');
+        }
+      });
+
+      wrap.addEventListener('pointerdown', wake, { passive: true });
+    })();
+  </script>
+</body>
